'use strict';

/**
* Return the index of the first element in a one-dimensional ndarray which passes a test implemented by a predicate function.
*
* @module @stdlib/blas-ext-base-ndarray-gfind-index
*
* @example
* var scalar2ndarray = require( '@stdlib/ndarray-from-scalar' );
* var vector = require( '@stdlib/ndarray-vector-ctor' );
* var gfindIndex = require( '@stdlib/blas-ext-base-ndarray-gfind-index' );
*
* function clbk( v ) {
*     return v % 2.0 === 0.0;
* }
*
* var x = vector( [ 1.0, 3.0, 4.0, 2.0 ], 'generic' );
*
* var fromIndex = scalar2ndarray( 0, {
*     'dtype': 'generic'
* });
*
* var v = gfindIndex( [ x, fromIndex ], clbk );
* // returns 2
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
